import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.*;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class RestrictByOneTypeOfResultVisitor_caseTopType_TriageGen2Test {

    @Mock
    private JSType mockTopType;

    @Mock
    private JSType mockValueType;

    @Mock
    private JSType mockNativeType;

    private TestableRestrictByOneTypeOfResultVisitor visitor;

    /**
     * Since the method is protected, we use a Testable subclass to expose it.
     */
    private static class TestableRestrictByOneTypeOfResultVisitor extends 
            com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor {

        private boolean resultEqualsValue;
        private Object value;

        public TestableRestrictByOneTypeOfResultVisitor(boolean resultEqualsValue, Object value) {
            this.resultEqualsValue = resultEqualsValue;
            this.value = value;
        }

        @Override
        public JSType caseTopType(JSType topType) {
            return super.caseTopType(topType);
        }

        // Overriding to allow mocking the internal dependency 'getNativeTypeForTypeOf'
        @Override
        protected JSType getNativeTypeForTypeOf(Object value) {
            return getNativeTypeForTypeOfInternal(value);
        }

        // This is a placeholder to be mocked via spy
        protected JSType getNativeTypeForTypeOfInternal(Object value) {
            return null;
        }
    }

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testCaseTopType_resultEqualsValueFalse() {
        // Arrange: resultEqualsValue is false
        visitor = new TestableRestrictByOneTypeOfResultVisitor(false, null);

        // Act
        JSType result = visitor.caseTopType(mockTopType);

        // Assert: Should return topType regardless of other logic
        assertThat(result).isEqualTo(mockTopType);
    }

    @Test
    public void testCaseTopType_resultEqualsValueTrue_typeByNameIsNull() {
        // Arrange: resultEqualsValue is true, but getNativeTypeForTypeOf returns null
        visitor = spy(new TestableRestrictByOneTypeOfResultVisitor(true, mockValueType));
        doReturn(null).when(visitor).getNativeTypeForTypeOfInternal(mockValueType);

        // Act
        JSType result = visitor.caseTopType(mockTopType);

        // Assert: Should return topType because typeByName was null
        assertThat(result).isEqualTo(mockTopType);
    }

    @Test
    public void testCaseTopType_resultEqualsValueTrue_typeByNameIsNotNull() {
        // Arrange: resultEqualsValue is true, and getNativeTypeForTypeOf returns a valid type
        visitor = spy(new TestableRestrictByOneTypeOfResultVisitor(true, mockValueType));
        doReturn(mockNativeType).when(visitor).getNativeTypeForTypeOfInternal(mockValueType);

        // Act
        JSType result = visitor.caseTopType(mockTopType);

        // Assert: Should return the native type found
        assertThat(result).isEqualTo(mockNativeType);
    }
}
